/**
 * NOVA_ATELIER_WORLD — Orbit Product Hero (Calibre NA-01)
 * 1. COMPOSITION: dark graded backdrop plane (7x6 @ z=-2.5) behind a low cylindrical
 *    plinth (r1.4 h0.25, top@y=-1.1) carrying the machined-metal watch (normalized to
 *    2.2 units tall, centered) inside a rotating pivot group; radial contact shadow
 *    beneath; headline/body/caption stacked below on the -y axis.
 * 2. LIGHT RIG: node-local rig-product-hero — warm key spot (65 @ [2.2,3.2,2.4]),
 *    cool fill point (4 @ [-2.8,0.9,2]), white rim spot (48 @ [-1.6,2.6,-2.2]) plus a
 *    capped (1.4) accent-red point grazing the left case flank for the signal highlight.
 * 3. MATERIALS: watch meshes upgraded to MeshPhysicalNodeMaterial (brushed metal:
 *    roughness .52, metalness .55, clearcoat .2, clearcoatRoughness .4, anisotropy .8);
 *    plinth roughness .7/metalness .3 near-black; backdrop TSL vertical 3-stop gradient;
 *    contact shadow is a procedural radial-falloff TSL alpha plane.
 * 4. MOTION: orbit primitive (load, 0.15 rad/s, radius 0.6) drives idle presentation;
 *    depth-rotate primitive (hover, maxDeg 6) tilts toward cursor via userData.handlers;
 *    weighted-settle GSAP entrance (scale 0->1.04->1.0) on the whole node.
 * 5. FOCAL ELEMENT: the machined-titanium watch case/bezel, key+rim lit, is the single
 *    brightest object in frame; the red accent only grazes its left flank (<=10% frame).
 */

import {
  Group,
  Mesh,
  PlaneGeometry,
  CylinderGeometry,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  SpotLight,
  PointLight,
  Object3D,
  Color,
  Box3,
  Vector3,
  DoubleSide,
} from 'three/webgpu';
import { uv, mix, smoothstep, vec3, length, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.55, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const root = new Group();
  root.name = 'orbit-product-hero';
  root.userData.handlers = {};

  const disposables = { geometries: [], materials: [], textures: [] };
  const primitiveHandles = [];
  const gsapTimelines = [];
  const lights = [];

  // ---------------------------------------------------------------------
  // color.gradient — backdrop plane with 3-stop vertical gradient (TSL)
  // ---------------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new Color(stops[0].hex);
  const c1 = new Color(stops[1].hex);
  const c2 = new Color(stops[2].hex);
  const v0 = vec3(c0.r, c0.g, c0.b);
  const v1 = vec3(c1.r, c1.g, c1.b);
  const v2 = vec3(c2.r, c2.g, c2.b);
  const t = uv().y;
  const seg1 = smoothstep(float(stops[0].at), float(stops[1].at), t);
  const seg2 = smoothstep(float(stops[1].at), float(stops[2].at), t);
  const gradientColorNode = mix(mix(v0, v1, seg1), v2, seg2);

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientColorNode;
  backdropMat.side = DoubleSide;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  backdrop.name = 'backdrop-gradient';
  root.add(backdrop);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(backdropMat);

  // ---------------------------------------------------------------------
  // color.surface / effects.spec — plinth (low cylinder)
  // ---------------------------------------------------------------------
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface ?? '#14141a'),
  });
  plinthMat.roughness = 0.7;
  plinthMat.metalness = 0.3;
  const plinthTopY = -1.1;
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, plinthTopY - 0.125, 0);
  plinth.name = 'plinth';
  root.add(plinth);
  disposables.geometries.push(plinthGeo);
  disposables.materials.push(plinthMat);

  // ---------------------------------------------------------------------
  // effects.spec — radial contact shadow (procedural TSL alpha falloff)
  // ---------------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centered = uv().sub(vec3(0.5, 0.5, 0).xy);
  const dist = length(centered).mul(2.0);
  const falloff = smoothstep(1.0, 0.0, dist).mul(0.55);
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = falloff;
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, plinthTopY - 0.25 - 0.001, 0);
  contactShadow.name = 'contact-shadow';
  root.add(contactShadow);
  disposables.geometries.push(shadowGeo);
  disposables.materials.push(shadowMat);

  // ---------------------------------------------------------------------
  // effects.spec — light rig (rig-product-hero + accent signal light)
  // ---------------------------------------------------------------------
  const key = new SpotLight(new Color('#fff2e0'), 65, 0, 0.5, 0.55, 1.5);
  key.position.set(2.2, 3.2, 2.4);
  key.target.position.set(0, 0.5, 0);
  root.add(key, key.target);
  lights.push(key);

  const fill = new PointLight(new Color('#d8dde6'), 4, 9, 2);
  fill.position.set(-2.8, 0.9, 2);
  root.add(fill);
  lights.push(fill);

  const rim = new SpotLight(new Color('#ffffff'), 48, 0, 0.6, 0.4, 1.5);
  rim.position.set(-1.6, 2.6, -2.2);
  rim.target.position.set(0, 0.7, 0);
  root.add(rim, rim.target);
  lights.push(rim);

  // color.accent — signal-red rim grazing the left case flank (glow-capped <=1.6)
  const accentLight = new PointLight(new Color(colors.accent ?? '#ff2a38'), 1.4, 4, 2);
  accentLight.position.set(-1.15, 0.35, 0.75);
  root.add(accentLight);
  lights.push(accentLight);

  // ---------------------------------------------------------------------
  // effects.spec — watch mesh (normalized 2.2 units tall, brushed-metal PBR)
  // ---------------------------------------------------------------------
  const watchPivot = new Group();
  watchPivot.name = 'watch-pivot';
  watchPivot.position.set(0, 0, 0);
  root.add(watchPivot);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene || gltf;
      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      box.getSize(size);
      const height = size.y || 1;
      const scale = 2.2 / height;
      scene.scale.setScalar(scale);

      const box2 = new Box3().setFromObject(scene);
      const center = new Vector3();
      box2.getCenter(center);
      scene.position.x -= center.x;
      scene.position.z -= center.z;
      scene.position.y -= box2.min.y;
      scene.position.y += plinthTopY;

      scene.traverse((child) => {
        if (child.isMesh) {
          const old = child.material;
          const mat = new MeshPhysicalNodeMaterial({
            color: old?.color ? old.color.clone() : new Color(0xaaaaaa),
            map: old?.map || null,
            normalMap: old?.normalMap || null,
            metalnessMap: old?.metalnessMap || null,
            roughnessMap: old?.roughnessMap || null,
          });
          mat.roughness = 0.52;
          mat.metalness = 0.55;
          mat.clearcoat = 0.2;
          mat.clearcoatRoughness = 0.4;
          if ('anisotropy' in mat) mat.anisotropy = 0.8;
          child.material = mat;
          disposables.materials.push(mat);
          disposables.geometries.push(child.geometry);
        }
      });

      watchPivot.add(scene);
    });
  }

  // ---------------------------------------------------------------------
  // text.headline.0 / text.body.1 / text.caption.2
  // ---------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Calibre NA-01', role: 'headline', typography: { fontSize: 68 } },
    { text: 'Machined in-house. 41 mm. Grade 5 titanium.', role: 'body', typography: { fontSize: 26 } },
    { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', role: 'caption', typography: { fontSize: 18 } },
  ];

  const headlineY = -1.5;
  const bodyY = headlineY - 0.25;
  const captionY = headlineY - 0.5;
  const textObjects = [];

  for (const item of items) {
    let y = bodyY;
    let color = colors.paper ?? '#e8ecf2';
    let letterSpacingPx = 0;
    let fontSize = item.typography?.fontSize ?? 26;
    if (item.role === 'headline') {
      y = headlineY;
      letterSpacingPx = -0.5;
    } else if (item.role === 'caption') {
      y = captionY;
      letterSpacingPx = fontSize * 0.08;
    }
    const textNode = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'center',
      letterSpacingPx,
    });
    textNode.position.set(0, y, 0.05);
    root.add(textNode);
    textObjects.push(textNode);
  }

  // ---------------------------------------------------------------------
  // primitive.orbit (load) + primitive.depth-rotate (hover)
  // ---------------------------------------------------------------------
  const orbitPrim = ctx.primitives['orbit'](watchPivot, {
    speed: 0.15,
    radius: 0.6,
    trigger: 'load',
  });
  primitiveHandles.push(orbitPrim);

  const depthRotatePrim = ctx.primitives['depth-rotate'](watchPivot, {
    maxDeg: 6,
    trigger: 'hover',
  });
  primitiveHandles.push(depthRotatePrim);

  root.userData.handlers.pointerenter = () => {
    depthRotatePrim.timeline?.play?.();
  };
  root.userData.handlers.pointerleave = () => {
    depthRotatePrim.timeline?.reverse?.();
  };

  // ---------------------------------------------------------------------
  // MOTION — weighted-settle entrance on the whole node
  // ---------------------------------------------------------------------
  root.scale.setScalar(0.001);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.6,
    ease: 'power3.out',
  }).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  gsapTimelines.push(entranceTl);

  // ---------------------------------------------------------------------
  // cleanup
  // ---------------------------------------------------------------------
  root.userData.cleanup = () => {
    gsapTimelines.forEach((tl) => tl.kill());
    primitiveHandles.forEach((p) => p?.cleanup?.());

    disposables.geometries.forEach((g) => g?.dispose?.());
    disposables.materials.forEach((m) => m?.dispose?.());
    disposables.textures.forEach((t) => t?.dispose?.());

    lights.forEach((l) => {
      if (l.target && l.target.parent) l.target.parent.remove(l.target);
      if (l.parent) l.parent.remove(l);
    });

    textObjects.forEach((t) => {
      t.parent?.remove(t);
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    });

    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m?.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });

    root.userData.handlers = {};
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.headline.0","where":"createNode/text-loop","how":"ctx.fontAtlas.createText headline at headlineY"},
  {"id":"text.body.1","where":"createNode/text-loop","how":"ctx.fontAtlas.createText body role at bodyY"},
  {"id":"text.caption.2","where":"createNode/text-loop","how":"ctx.fontAtlas.createText caption at captionY letterSpaced"},
  {"id":"color.background","where":"createNode/backdrop-gradient","how":"gradient stop 0 #0b0b10 in colorNode"},
  {"id":"color.surface","where":"createNode/plinth","how":"plinthMat color set to colors.surface"},
  {"id":"color.ink","where":"createNode/gradient-stops","how":"gradient stop 1 #16161d used as v2"},
  {"id":"color.paper","where":"createNode/text-loop","how":"text color defaults to colors.paper"},
  {"id":"color.accent","where":"createNode/accentLight","how":"PointLight colored colors.accent grazing case"},
  {"id":"color.gradient","where":"createNode/backdrop-gradient","how":"3-stop TSL mix/smoothstep vertical gradient"},
  {"id":"effects.spec","where":"createNode/glbLoader.then + plinth + contactShadow","how":"normalized mesh, PBR upgrade, plinth, shadow"},
  {"id":"primitive.orbit","where":"createNode/orbitPrim","how":"ctx.primitives.orbit applied to watchPivot on load"},
  {"id":"primitive.depth-rotate","where":"createNode/depthRotatePrim + handlers","how":"hover handlers play/reverse depth-rotate timeline"}
]}
*/
